package local.pullclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;
import net.minecraft.client.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.level.GameType;import net.minecraft.world.level.block.Blocks;import net.minecraft.core.BlockPos;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.spell_engine.internals.*;
@Mod(value="pull_client_probe",dist=Dist.CLIENT) public class PullClientProbe {
 int ticks,phase,at,stage;boolean pending;UUID caster;double start;final List<String> lines=Collections.synchronizedList(new ArrayList<>());final AtomicReference<Throwable> error=new AtomicReference<>();
 public PullClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean ok,String name){lines.add((ok?"PASS ":"FAIL ")+name);if(!ok)throw new AssertionError(name);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> job){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{job.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void step(){phase++;at=ticks;}
 void finish(){if(phase==99)return;phase=99;var mc=Minecraft.getInstance();mc.options.keyUp.setDown(false);mc.options.keySprint.setDown(false);try{Files.write(mc.gameDirectory.toPath().resolve("pull-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("pull-client-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.getSingleplayerServer()==null)return;if(ticks-at>1800)throw new AssertionError("Timeout "+phase);
  if(phase==0){mc.options.pauseOnLostFocus=false;mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);server(p->{p.setGameMode(GameType.SURVIVAL);p.removeAllEffects();p.getInventory().clearContent();p.setInvulnerable(true);p.getAttribute(Attributes.SCALE).setBaseValue(1);var speed=p.getAttribute(Attributes.MOVEMENT_SPEED);for(var m:List.copyOf(speed.getModifiers()))speed.removeModifier(m.id());speed.setBaseValue(.1);p.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(0);for(int x=-16;x<=16;x++)for(int z=-16;z<=16;z++)p.level().setBlockAndUpdate(new BlockPos(x,100,z),Blocks.STONE.defaultBlockState());p.teleportTo(0,101,6);p.setNoGravity(false);p.setDeltaMovement(0,0,0);var e=EntityTypes.CREEPER.create(p.level(),EntitySpawnReason.COMMAND);e.setNoAi(true);e.setPos(0,101,0);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(10000);e.setHealth(10000);p.level().addFreshEntity(e);caster=e.getUUID();});step();return;}
  if(ticks-at<30)return;
  if(phase%2==1&&phase<7){mc.setScreenAndShow(null);mc.player.setYRot(0);mc.player.setXRot(18);mc.options.keyUp.setDown(true);mc.options.keySprint.setDown(true);start=mc.player.getZ();stage=(phase-1)/2;server(p->{var e=(LivingEntity)p.level().getEntity(caster);long now=p.level().getGameTime();PaladinUltimates.startChannel(e,now-stage*200-14);PaladinUltimates.channelOf(e).pulses=stage*20+1;});step();return;}
  if(phase%2==0&&phase<=6){double delta=mc.player.getZ()-start;lines.add("STAGE "+stage+" outward displacement "+delta+" sprint="+mc.player.isSprinting()+" speed="+mc.player.getAttributeValue(Attributes.MOVEMENT_SPEED));check(stage==0?delta>.3:delta<-.15,"Native sprint contest stage "+stage);Screenshot.grab(mc,false);mc.options.keyUp.setDown(false);mc.options.keySprint.setDown(false);server(p->{var e=(LivingEntity)p.level().getEntity(caster);PaladinUltimates.end(e,PaladinUltimates.End.CLEANUP);p.teleportTo(0,101,6);p.setDeltaMovement(0,0,0);p.setKnownMovement(net.minecraft.world.phys.Vec3.ZERO);});step();return;}
  if(phase==7){check(mc.level.getEntitiesOfClass(net.paladins.entity.BarrierEntity.class,mc.player.getBoundingBox().inflate(20),PurgatoryBoundary::is).isEmpty(),"Boundary removed after native channel end");finish();}
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
